17	/// Build an OAuth error redirect (303) to `redirect_uri` with error parameters.
18	///
19	/// `issuer` is emitted as the RFC 9207 `iss` parameter. The AT Protocol OAuth metadata
20	/// advertises `authorization_response_iss_parameter_supported: true`, so a conformant
21	/// client validates `iss` on every authorization response — including error responses
22	/// (e.g. the user denying) — and rejects one that omits it. Error responses use the
23	/// same `response_mode` as a success would (a fragment-mode client only reads the
24	/// fragment, so a query-string error is invisible to it).
25	pub(super) fn error_redirect(
26	    redirect_uri: &str,
27	    error: &str,
28	    description: &str,
29	    state: &str,
30	    issuer: &str,
31	    mode: ResponseMode,
32	) -> Redirect {
33	    // Structured trace of every authorization-response error: the redirect delivers the
34	    // error to the client, not the operator, so without this line a failed authorize leg
35	    // is only a bare 3xx in the request counters. Mechanical facts only.
36	    tracing::info!(
37	        error,
38	        description,
39	        "OAuth authorization error redirect issued"
40	    );
41	    let url = format!(
42	        "{}{}error={}&error_description={}&state={}&iss={}",
43	        redirect_uri,
44	        mode.separator(redirect_uri),
45	        encode_param(error),
46	        encode_param(description),
47	        encode_param(state),
48	        encode_param(issuer),
49	    );
50	    Redirect::to(&url)
51	}
