301	/// Render the wallet-approval block: a scan QR encoding the `request_id` (+ origin) for the
302	/// cross-device phone-scan path, the human-typeable `user_code` fallback (no camera / accessibility),
303	/// an "Open in Obsign" handoff link carrying the same payload for the same-device path, a live status
304	/// region, and a no-JS "I've approved — continue" form that POSTs to `/oauth/authorize/complete`. An
305	/// inline script polls `GET /oauth/authorize/status` (backing off on the `slow_down` 429) and, on
306	/// approval, submits the same completion form — so JS and no-JS reach the identical completion path.
307	fn render_wallet_path(w: &WalletConsentPath) -> String {
308	    let request_id = html_escape(w.request_id);
309	    let user_code = html_escape(w.user_code);
310	    let handoff = wallet_handoff_uri(w.request_id, w.origin);
311	    let mut html = String::with_capacity(2048);
312	    html.push_str("    <div class=\"section-label\">Approve in your wallet</div>\n");
313	    html.push_str("    <div class=\"wallet\" id=\"wallet-path\" data-request-id=\"");
314	    html.push_str(&request_id);
315	    html.push_str("\">\n");
316	    // Push-delivered prompt (Phase C): the number-match panel leads. The wallet will refuse to
317	    // approve without this number, so a user whose phone just buzzed reads this block first;
318	    // everything below stays rendered as the fallback channels for the same request.
319	    if let Some(match_code) = w.match_code {
320	        html.push_str(
321	            "      <p class=\"wallet-lead\">We sent a sign-in request to your wallet. To approve it, enter this number in Obsign:</p>\n",
322	        );
323	        html.push_str("      <div class=\"match-code mono\" id=\"match-code\">");
324	        html.push_str(&html_escape(match_code));
325	        html.push_str("</div>\n");
326	        html.push_str(
327	            "      <p class=\"wallet-lead wallet-or\">No notification? Scan or type the code below instead — you'll still be asked for the number above.</p>\n",
328	        );
329	    }
330	    // Scan path first: the strongest cross-device channel (start from the page, no transcription).
331	    // Rendered only when the payload actually fits in a QR — otherwise the typed code below stands
332	    // in, and nothing about the fallback changes.
333	    if let Some(qr) = render_qr_svg(&handoff) {
334	        html.push_str(
335	            "      <p class=\"wallet-lead\">Scan this with Obsign on your phone to sign in with your device key:</p>\n",
336	        );
337	        html.push_str("      <div class=\"qr\">");
338	        html.push_str(&qr);
339	        html.push_str("</div>\n");
340	        html.push_str(
341	            "      <p class=\"wallet-lead wallet-or\">No camera? Open Obsign and enter this code:</p>\n",
342	        );
343	    } else {
344	        html.push_str(
345	            "      <p class=\"wallet-lead\">Open Obsign and enter this code to sign in with your device key:</p>\n",
346	        );
347	    }
348	    html.push_str("      <div class=\"user-code mono\">");
349	    html.push_str(&user_code);
350	    html.push_str("</div>\n");
351	    html.push_str("      <a class=\"btn btn-approve wallet-open\" href=\"");
352	    html.push_str(&html_escape(&handoff));
353	    html.push_str("\">");
354	    html.push_str(ICON_SEAL_SM);
355	    html.push_str("Open in Obsign</a>\n");
356	    html.push_str(
357	        "      <p class=\"wallet-status\" id=\"wallet-status\" role=\"status\" aria-live=\"polite\">Waiting for approval in your wallet…</p>\n",
358	    );
359	    html.push_str(
360	        "      <form method=\"POST\" action=\"/oauth/authorize/complete\" id=\"complete-form\">\n",
361	    );
362	    html.push_str("        <input type=\"hidden\" name=\"request_id\" value=\"");
363	    html.push_str(&request_id);
364	    html.push_str("\" />\n");
365	    html.push_str(
366	        "        <button type=\"submit\" class=\"btn btn-deny wallet-continue\">I've approved — continue</button>\n",
367	    );
368	    html.push_str("      </form>\n");
369	    html.push_str("    </div>\n");
370	    html.push_str(WALLET_POLL_SCRIPT);
371	    html
372	}
