374	/// Inline poller for the wallet path. Reads the `request_id` from the block's data attribute, polls
375	/// the status endpoint on a backoff that widens when it sees the `slow_down` 429, and submits the
376	/// completion form on approval. If CSP or a JS-off client blocks it, the no-JS continue button is
377	/// the fallback — the whole flow still completes.
378	const WALLET_POLL_SCRIPT: &str = r#"    <script>
379	    (function(){
380	      var el=document.getElementById('wallet-path');
381	      if(!el)return;
382	      var rid=el.getAttribute('data-request-id');
383	      var status=document.getElementById('wallet-status');
384	      var form=document.getElementById('complete-form');
385	      var interval=3000;
386	      function schedule(){setTimeout(poll,interval);}
387	      function poll(){
388	        fetch('/oauth/authorize/status?request_id='+encodeURIComponent(rid),{headers:{'Accept':'application/json'}})
389	          .then(function(r){
390	            if(r.status===429){interval=Math.min(interval+2000,15000);schedule();return null;}
391	            return r.json();
392	          })
393	          .then(function(d){
394	            if(!d)return;
395	            if(d.status==='approved'){status.textContent='Approved — continuing…';form.submit();return;}
396	            if(d.status==='denied'){status.textContent='This request was denied in your wallet.';return;}
397	            if(d.status==='expired'){status.textContent='This request expired. Reload the page to try again.';return;}
398	            if(d.status==='completed'){return;}
399	            schedule();
400	          })
401	          .catch(function(){schedule();});
402	      }
403	      schedule();
404	    })();
405	    </script>
406	"#;
