410	/// Percent-encode a string for safe inclusion as a URL query parameter value.
411	pub(super) fn encode_param(s: &str) -> String {
412	    let mut out = String::with_capacity(s.len());
413	    for b in s.bytes() {
414	        match b {
415	            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
416	                out.push(b as char)
417	            }
418	            _ => out.push_str(&format!("%{b:02X}")),
419	        }
420	    }
421	    out
422	}
