424	/// Render `data` as an inline, self-contained SVG QR code, or `None` if it does not fit in a QR
425	/// (the caller then falls back to the typed code, never breaking the page). Dark modules are drawn
426	/// as one `<path>` on a white ground with a 4-module quiet zone — dark-on-light with a fixed white
427	/// background so it scans regardless of the viewer's page theme. Pure: no I/O, deterministic.
428	fn render_qr_svg(data: &str) -> Option<String> {
429	    // Medium error correction balances density against scan robustness on a phone camera.
430	    let qr = qrcodegen::QrCode::encode_text(data, qrcodegen::QrCodeEcc::Medium).ok()?;
431	    const QUIET: i32 = 4;
432	    let size = qr.size();
433	    let dim = size + 2 * QUIET;
434	
435	    // One path of "M{x} {y}h1v1h-1z" per dark module — compact and crisp at any rendered size.
436	    use std::fmt::Write as _;
437	    let mut modules = String::new();
438	    for y in 0..size {
439	        for x in 0..size {
440	            if qr.get_module(x, y) {
441	                let _ = write!(modules, "M{} {}h1v1h-1z", x + QUIET, y + QUIET);
442	            }
443	        }
444	    }
445	
446	    Some(format!(
447	        "<svg viewBox=\"0 0 {dim} {dim}\" width=\"196\" height=\"196\" role=\"img\" \
448	         aria-label=\"QR code to sign in with the Obsign wallet\" \
449	         xmlns=\"http://www.w3.org/2000/svg\" shape-rendering=\"crispEdges\">\
450	         <rect width=\"{dim}\" height=\"{dim}\" fill=\"#ffffff\"/>\
451	         <path d=\"{modules}\" fill=\"#1b1b1f\"/></svg>"
452	    ))
453	}
