455	/// HTML-escape a string for safe embedding in HTML content or attribute values.
456	pub(super) fn html_escape(s: &str) -> String {
457	    s.replace('&', "&amp;")
458	        .replace('<', "&lt;")
459	        .replace('>', "&gt;")
460	        .replace('"', "&quot;")
461	        .replace('\'', "&#39;")
462	}
