1	// pattern: Imperative Shell
2	//
3	// Gathers: instance metadata from config
4	// Processes: render_landing (pure template substitution)
5	// Returns: the HTML landing page served at `/`
6	//
7	// Visual system: "The Sealed Credential" (see DESIGN.md), matching the OAuth consent
8	// page. The template is embedded via include_str! so the deployed OCI container needs
9	// no asset directory; brand fonts come from the PDS's own /static/fonts route.
10	
11	use axum::{extract::State, response::Html};
12	use common::Config;
13	
14	use crate::app::AppState;
15	
16	const LANDING_TEMPLATE: &str = include_str!("../../assets/landing.html");
17	
18	/// `GET /` — the instance landing page: what this server is, its public facts
19	/// (host, DID, version, signup policy), and where people and tools go next.
20	pub async fn landing(State(state): State<AppState>) -> Html<String> {
21	    Html(render_landing(&state.config))
22	}
23	
24	/// Pure template render: substitute escaped instance facts into the embedded page.
25	fn render_landing(config: &Config) -> String {
26	    let host = config.public_host();
27	    let did = config.resolve_server_did();
28	    let domains = if config.available_user_domains.is_empty() {
29	        "none configured".to_string()
30	    } else {
31	        config.available_user_domains.join(", ")
32	    };
33	    let signup = if config.invite_code_required {
34	        "claim code required"
35	    } else {
36	        "open"
37	    };
38	    let contact_row = match &config.contact.email {
39	        Some(email) => {
40	            let escaped = html_escape(email);
41	            format!(
42	                "        <dt>contact</dt>\n        <dd><a href=\"mailto:{escaped}\">{escaped}</a></dd>"
43	            )
44	        }
45	        None => String::new(),
46	    };
47	
48	    LANDING_TEMPLATE
49	        .replace("{{host}}", &html_escape(host))
50	        .replace("{{did}}", &html_escape(&did))
51	        .replace("{{version}}", env!("CARGO_PKG_VERSION"))
52	        .replace("{{domains}}", &html_escape(&domains))
53	        .replace("{{signup}}", signup)
54	        .replace("{{contact_row}}", &contact_row)
55	}
56	
57	/// HTML-escape a string for safe embedding in HTML content or attribute values.
58	fn html_escape(s: &str) -> String {
59	    s.replace('&', "&amp;")
60	        .replace('<', "&lt;")
61	        .replace('>', "&gt;")
62	        .replace('"', "&quot;")
63	        .replace('\'', "&#39;")
64	}
