757	///
758	/// Re-validates client_id and redirect_uri against the database, and enforces
759	/// code_challenge_method=S256, before issuing an authorization code or redirect.
760	/// Hidden form fields could be tampered with by a malicious browser.
761	pub async fn post_authorization(
762	    State(state): State<AppState>,
763	    Form(form): Form<ConsentForm>,
764	) -> Response {
765	    // RFC 9207 issuer identifier, emitted as `iss` on every authorization response.
766	    // Trailing slash trimmed to match the AS-metadata `issuer` value exactly.
767	    let issuer = state.config.public_url.trim_end_matches('/').to_string();
768	    // Validate client and redirect_uri first — deny/approve both redirect there,
769	    // so we must confirm it is safe before using it as a redirect target.
770	    let metadata = match lookup_and_validate_client(&state, &form.client_id, &form.redirect_uri)
771	        .await
772	    {
773	        Ok(m) => m,
774	        Err(ClientValidationError::UnknownClient) => {
775	            return error_page("Unknown Client", "The client_id is not registered.").into_response()
776	        }
777	        Err(ClientValidationError::ResolutionFailed(desc)) => {
778	            return error_page(
779	                "Unknown Client",
780	                &format!("The client_id could not be resolved: {desc}"),
781	            )
782	            .into_response()
783	        }
784	        Err(ClientValidationError::PrivateUseRedirectMismatch(desc)) => {
785	            return error_page("Invalid Redirect URI", &desc).into_response()
786	        }
787	        Err(ClientValidationError::DbError) => {
788	            return error_page("Server Error", "A database error occurred.").into_response()
789	        }
790	        Err(ClientValidationError::MalformedMetadata) => {
791	            return error_page(
792	                "Client Configuration Error",
793	                "Client metadata is malformed.",
794	            )
795	            .into_response()
796	        }
797	        Err(ClientValidationError::InvalidRedirectUri) => {
798	            return error_page(
799	                "Invalid Redirect URI",
800	                "The redirect_uri does not match the client's registered URIs.",
801	            )
802	            .into_response()
803	        }
804	    };
